function normalizeMonsterId(monsterOrId) {
  const raw = Number(typeof monsterOrId === 'object' ? (monsterOrId?.baseId ?? monsterOrId?.id) : monsterOrId);
  if (!Number.isFinite(raw) || raw <= 0) return null;
  const id = Math.floor(raw);
  return LEGACY_ORIGINAL_MONSTER_ID_MAP[id] || id;
}

function migrateMonsterId(monsterOrId, fromVersion = MONSTER_ID_SCHEMA_VERSION) {
  const raw = Number(typeof monsterOrId === 'object' ? (monsterOrId?.baseId ?? monsterOrId?.id) : monsterOrId);
  if (!Number.isFinite(raw) || raw <= 0) return null;
  let id = Math.floor(raw);
  if (LEGACY_ORIGINAL_MONSTER_ID_MAP[id]) id = LEGACY_ORIGINAL_MONSTER_ID_MAP[id];
  const version = Number(fromVersion || 0);
  if (version < 3) id = MONSTER_ID_V2_TO_V3_MAP[id] || id;
  if (version < 4) id = MONSTER_ID_V3_TO_V4_MAP[id] || id;
  return id;
}

function formatMonsterId(monsterOrId) {
  const id = normalizeMonsterId(monsterOrId);
  return id === null ? '' : String(id).padStart(6, '0');
}

